sections.usage:
# Render with the kit: irender render page.yaml --ui-kit
version: 1
state: { name: "" }
root:
  type: ui-card
  props: { title: Welcome, description: Every component is plain config. }
  children:
    - { type: ui-input, props: { bind: name, placeholder: Your name } }
    - type: ui-button
      props: { label: "Say hi to {{ name || 'you' }}" }
      on: { click: { action: set_state, key: toast, value: { title: Hi! } } }

- { type: ui-theme-toggle }                                   # System, Light, Dark
- { type: ui-theme-option, props: { option: palette, swatch: color.primary } }
- { type: ui-popover, props: { trigger: Theme }, children: [ { type: ui-theme-panel } ] }

- type: ui-button
  props: { label: Save, variant: default, size: sm, icon: check }
  on: { click: { action: submit, endpoint: /api/save, method: POST } }
- { type: ui-button, props: { label: Docs, variant: link, href: /docs } }

- type: ui-split-button
  props: { label: Download PDF }
  on: { click: { action: call, name: download, args: { format: pdf } } }
  children:
    - { type: ui-menu-item, props: { label: Excel }, on: { click: { action: call, name: download, args: { format: xlsx } } } }

- { type: ui-toggle, props: { bind: bold, label: Bold } }
- { type: ui-toggle-group, props: { bind: align, options: [left, center, right] } }
- { type: ui-slider, props: { bind: volume, min: 0, max: 100, step: 5 } }

- { type: ui-label, props: { text: Email, for: email } }
- { type: ui-input, props: { bind: email, type: email, placeholder: you@example.com }, attrs: { id: email } }
- { type: ui-select, props: { bind: plan, options: [Free, Pro, Team] } }
- { type: ui-checkbox, props: { bind: terms, label: I accept the terms } }
- { type: ui-radio-group, props: { bind: size, options: [S, M, L] } }

- type: ui-field
  props: { label: Username, description: 3 to 20 letters, error: "{{ username.length < 3 ? 'Too short' : '' }}" }
  children: [ { type: ui-input, props: { bind: username } } ]
- type: ui-input-group
  props: { prefix: "https://", suffix: .com }
  children: [ { type: ui-input, props: { bind: site } } ]

- type: ui-field
  props: { label: Verification code, error: "{{ codeError }}" }
  children:
    - type: ui-input-otp
      props: { bind: code, length: 6, groups: [3, 3] }
      on: { complete: { action: submit, endpoint: /api/verify, method: POST, body: { code: "{{ code }}" }, into: result } }

- type: ui-date-picker
  props: { bind: period, bindRange: periodDates, mode: range, months: 2, presets: [last7, thisMonth, yearToDate] }
- { type: ui-date-picker, props: { bind: due, input: true, min: today, bindError: dueError } }
- { type: ui-calendar, props: { bind: days, mode: multiple, disabledDays: [0, 6] } }

- type: ui-card
  props: { title: Create project, description: Deploy in one click. }
  children:
    - { type: ui-input, props: { bind: project, placeholder: Name } }
    - type: ui-card-footer
      children: [ { type: ui-button, props: { label: Deploy } } ]

- { type: ui-avatar, props: { src: /me.jpg, alt: Kaushik, fallback: KS } }
- type: ui-aspect-ratio
  props: { ratio: "16 / 9" }
  children: [ { type: element, props: { tag: img }, attrs: { src: /cover.jpg, alt: "" } } ]

- type: ui-table
  props: { caption: Recent invoices }
  children:
    - type: list
      props: { tag: tbody, items: "{{ invoices }}", as: inv }
      children:
        - { type: element, props: { tag: tr }, children: [ { type: text, props: { tag: td, value: "{{ inv.id }}" } } ] }

- type: ui-data-table
  props: { rows: "{{ orders }}", search: true, selectable: true, bindSelection: picked, pageSize: 10 }
  children:
    - { type: ui-data-table-column, props: { field: date, format: date, filter: date } }
    - { type: ui-data-table-column, props: { field: amount, format: currency, filter: range, summary: sum } }
    - { type: ui-data-table-column, props: { field: status, filter: select, cell: badge } }

- { type: ui-heading, props: { level: 2, text: Settings } }
- { type: ui-text, props: { variant: muted, text: Manage your account. } }
- { type: ui-separator, props: { label: Or continue with } }

- { type: ui-toaster, props: { bind: toast } }
- type: ui-button
  props: { label: Save }
  on: { click: { action: set_state, key: toast, value: { title: Saved, description: Your changes are live. } } }

- { type: ui-illustration, props: { name: not-found, size: 320 } }
- { type: ui-illustration, props: { name: out-of-stock, primary: "#0ea5e9", secondary: "#f43f5e" } }
- type: ui-empty
  props: { illustration: no-data, title: No data yet, description: Orders show up here. }
  children: [ { type: ui-button, props: { label: Import orders } } ]

- { type: ui-spinner, props: { label: Loading orders } }
- { type: ui-empty, props: { title: No projects yet, description: Create your first one. } }
- { type: ui-scroll-area, props: { height: 200 }, children: [ … ] }

- type: ui-dialog
  props: { trigger: Edit profile, title: Edit profile, description: Make changes here. }
  children:
    - { type: ui-input, props: { bind: name } }
    - type: ui-dialog-footer
      children: [ { type: ui-dialog-close, props: { label: Save } } ]

- type: ui-dropdown-menu
  props: { trigger: My account }
  children:
    - { type: ui-menu-label, props: { text: Signed in as Ada } }
    - { type: ui-menu-item, props: { label: Profile, shortcut: ⇧⌘P } }
    - { type: ui-menu-separator }
    - { type: ui-menu-item, props: { label: Log out, variant: destructive } }
- { type: ui-tooltip, props: { text: Add to library }, children: [ { type: ui-button, props: { label: + } } ] }

- type: ui-context-menu
  props: { bind: file }
  children:
    - { type: element, attrs: { data-context: Report.pdf }, children: [ { type: text, props: { value: Report.pdf } } ] }
    - { type: ui-menu-item, props: { label: "Open {{ file }}" } }
    - { type: ui-menu-item, props: { label: Delete, variant: destructive } }

- type: ui-command-dialog
  props: { trigger: Search, shortcut: mod+k }
  children:
    - type: ui-command-group
      props: { heading: Pages }
      children:
        - { type: ui-command-item, props: { label: Dashboard, href: /dashboard } }
        - { type: ui-command-item, props: { label: Settings, keywords: [preferences], href: /settings } }

- type: ui-tabs
  props: { bind: tab }
  children:
    - { type: ui-tab-panel, props: { value: account, label: Account }, children: [ … ] }
    - { type: ui-tab-panel, props: { value: password, label: Password }, children: [ … ] }

- type: ui-menubar
  children:
    - type: ui-menubar-menu
      props: { label: File }
      children:
        - { type: ui-menu-item, props: { label: New tab, shortcut: ⌘T } }
        - type: ui-menu-sub
          props: { label: Share }
          children: [ { type: ui-menu-item, props: { label: Email link } } ]
    - type: ui-menubar-menu
      props: { label: View }
      children:
        - { type: ui-menu-checkbox, props: { label: Show status bar, bind: statusBar } }
        - { type: ui-menu-radio-group, props: { bind: zoom, options: [100%, 125%, 150%] } }

- type: ui-navigation-menu
  children:
    - type: ui-navigation-item
      props: { label: Products, width: 420 }
      children:
        - { type: ui-navigation-link, props: { label: Analytics, href: /analytics, description: See what's happening } }
        - { type: ui-navigation-link, props: { label: Automation, href: /automation, description: Let it run itself } }
    - { type: ui-navigation-link, props: { label: Docs, href: /docs, active: true } }

- type: ui-carousel
  props: { label: Featured, size: 280 }
  children: [ { type: ui-card, props: { title: One } }, { type: ui-card, props: { title: Two } } ]
